package com.primehr.succession.application;

import com.primehr.integration.administrative.PermissionDataScope;
import com.primehr.shared.audit.PrimeHrAuditService;
import com.primehr.shared.exception.*;
import com.primehr.succession.api.SuccessionContinuityDtos.*;
import com.primehr.succession.domain.*;
import com.primehr.succession.infrastructure.*;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.*;
import java.util.*;

@Service
@Transactional
public class SuccessionContinuityServiceImpl implements SuccessionContinuityService {
    private static final ZoneId AGENCY_ZONE = ZoneId.of("Asia/Manila");
    private final SuccessionContinuityPlanRepository plans; private final SuccessionBenchCoverageEntryRepository bench;
    private final SuccessionRspReferralPacketRepository referrals; private final SuccessionRspReferralEventRepository referralEvents;
    private final SuccessionContinuityRiskReviewRepository risks; private final SuccessionCycleRepository cycles;
    private final SuccessionCriticalPositionDesignationRepository designations; private final SuccessionCommitteeMemberRepository members;
    private final SuccessionCommitteeConflictRepository conflicts;
    private final SuccessionCandidateRepository candidates; private final SuccessionReadinessAssessmentRepository assessments;
    private final SuccessionPoolDecisionRepository decisions; private final SuccessionPoolMembershipEventRepository memberships;
    private final SuccessionDevelopmentPlanRepository developments; private final RspReferralSourcePort rsp; private final PrimeHrAuditService audit;

    public SuccessionContinuityServiceImpl(SuccessionContinuityPlanRepository plans,SuccessionBenchCoverageEntryRepository bench,SuccessionRspReferralPacketRepository referrals,SuccessionRspReferralEventRepository referralEvents,SuccessionContinuityRiskReviewRepository risks,SuccessionCycleRepository cycles,SuccessionCriticalPositionDesignationRepository designations,SuccessionCommitteeMemberRepository members,SuccessionCommitteeConflictRepository conflicts,SuccessionCandidateRepository candidates,SuccessionReadinessAssessmentRepository assessments,SuccessionPoolDecisionRepository decisions,SuccessionPoolMembershipEventRepository memberships,SuccessionDevelopmentPlanRepository developments,RspReferralSourcePort rsp,PrimeHrAuditService audit){this.plans=plans;this.bench=bench;this.referrals=referrals;this.referralEvents=referralEvents;this.risks=risks;this.cycles=cycles;this.designations=designations;this.members=members;this.conflicts=conflicts;this.candidates=candidates;this.assessments=assessments;this.decisions=decisions;this.memberships=memberships;this.developments=developments;this.rsp=rsp;this.audit=audit;}

    @Override @Transactional(readOnly=true) public List<PlanResponse>listPlans(String a,String actor,PermissionDataScope scope){return plans.findByAgencyIdOrderByCreatedAtDesc(a).stream().filter(p->visible(a,p,actor,scope)).map(p->planResponse(a,p)).toList();}
    @Override @Transactional(readOnly=true) public PlanResponse getPlan(String a,String id,String actor,PermissionDataScope scope){var p=plan(a,id);authorize(a,p,actor,scope);return planResponse(a,p);}
    @Override public PlanResponse createPlan(String a,String riskId,PlanInput i,String actor,PermissionDataScope scope,String c){var risk=risks.findByIdAndAgencyId(riskId,a).orElseThrow(()->new ResourceNotFoundException("Continuity risk review not found"));var cycle=cycle(a,risk.getCycleId());authority(a,cycle,actor,scope);check(risk.getVersion(),i.recordVersion());if(plans.findByAgencyIdAndRiskReviewId(a,riskId).isPresent())throw new OptimisticConflictException("A continuity plan already exists for this risk review");var designation=designation(a,risk.getDesignationId());if(designation.getStatus()!=SuccessionCriticalPositionDesignation.Status.APPROVED||!designation.getSourceFingerprint().equals(risk.getTargetFingerprint()))throw new OptimisticConflictException("Critical-position designation is no longer an approved exact source");var p=plans.saveAndFlush(new SuccessionContinuityPlan(a,risk,cycle,i.criticalFunctions(),i.interimArrangement(),i.continuityActions(),i.activationTriggers(),i.targetRecoveryDays(),i.reviewOn()));var out=planResponse(a,p);record(a,"CREATE_SUCCESSION_CONTINUITY_PLAN",p,out,null,c);return out;}
    @Override public PlanResponse updatePlan(String a,String id,PlanInput i,String actor,PermissionDataScope scope,String c){var p=plan(a,id);authority(a,cycle(a,p.getCycleId()),actor,scope);check(p.getVersion(),i.recordVersion());p.update(i.criticalFunctions(),i.interimArrangement(),i.continuityActions(),i.activationTriggers(),i.targetRecoveryDays(),i.reviewOn());plans.saveAndFlush(p);var out=planResponse(a,p);record(a,"UPDATE_SUCCESSION_CONTINUITY_PLAN",p,out,null,c);return out;}
    @Override public PlanResponse submitPlan(String a,String id,VersionInput i,String actor,PermissionDataScope scope,String c){var p=plan(a,id);authority(a,cycle(a,p.getCycleId()),actor,scope);check(p.getVersion(),i.recordVersion());p.submit(actor,Instant.now());plans.saveAndFlush(p);var out=planResponse(a,p);record(a,"SUBMIT_SUCCESSION_CONTINUITY_PLAN",p,out,null,c);return out;}
    @Override public PlanResponse approvePlan(String a,String id,DecisionInput i,String actor,PermissionDataScope scope,String c){var p=plan(a,id);authority(a,cycle(a,p.getCycleId()),actor,scope);check(p.getVersion(),i.recordVersion());p.approve(actor,i.reason(),Instant.now());plans.saveAndFlush(p);var out=planResponse(a,p);record(a,"APPROVE_SUCCESSION_CONTINUITY_PLAN",p,out,i.reason(),c);return out;}
    @Override public PlanResponse finalizePlan(String a,String id,VersionInput i,String actor,PermissionDataScope scope,String c){var p=plan(a,id);authority(a,cycle(a,p.getCycleId()),actor,scope);check(p.getVersion(),i.recordVersion());var designation=designation(a,p.getDesignationId());if(designation.getStatus()!=SuccessionCriticalPositionDesignation.Status.APPROVED||!designation.getSourceFingerprint().equals(p.getTargetFingerprint()))throw new OptimisticConflictException("Critical-position designation is no longer an approved exact source");if(!bench.findByAgencyIdAndContinuityPlanIdOrderByEmployeeNo(a,id).isEmpty())throw new OptimisticConflictException("Bench coverage was already frozen");LocalDate today=LocalDate.now(AGENCY_ZONE);int count=0;for(var candidate:candidates.findByAgencyIdAndCycleIdAndDesignationIdOrderByEmployeeNo(a,p.getCycleId(),p.getDesignationId())){if(candidate.getStatus()!=SuccessionCandidate.Status.ELIGIBLE)continue;var assessment=assessments.findByAgencyIdAndCandidateId(a,candidate.getId()).orElse(null);if(assessment==null)continue;var decision=decisions.findByAgencyIdAndAssessmentId(a,assessment.getId()).orElse(null);if(decision==null||decision.getOutcome()!=SuccessionPoolDecision.Outcome.INCLUDED)continue;var current=memberships.findFirstByAgencyIdAndPoolDecisionIdOrderByEventSequenceDesc(a,decision.getId()).orElse(null);if(current==null||current.getResultingStatus()!=SuccessionPoolMembershipEvent.ResultingStatus.ACTIVE||current.getExpiresOn()==null||today.isAfter(current.getExpiresOn())||today.isBefore(current.getEffectiveOn()))continue;var development=developments.findByAgencyIdAndPoolDecisionId(a,decision.getId()).orElse(null);bench.saveAndFlush(new SuccessionBenchCoverageEntry(a,id,candidate,decision,current,development,Instant.now()));count++;}p.finalizePlan(actor,count,Instant.now());plans.saveAndFlush(p);var out=planResponse(a,p);record(a,"FINALIZE_SUCCESSION_CONTINUITY_PLAN",p,out,"Frozen active bench count: "+count,c);return out;}

    @Override @Transactional(readOnly=true) public List<ReferralResponse>listReferrals(String a,String actor,PermissionDataScope scope){return referrals.findByAgencyIdOrderByCreatedAtDesc(a).stream().filter(r->visible(a,plan(a,r.getContinuityPlanId()),actor,scope)).map(r->referralResponse(a,r)).toList();}
    @Override @Transactional(readOnly=true) public ReferralResponse getReferral(String a,String id,String actor,PermissionDataScope scope){var r=referral(a,id);authorize(a,plan(a,r.getContinuityPlanId()),actor,scope);return referralResponse(a,r);}
    @Override public ReferralResponse createReferral(String a,String planId,ReferralCreate i,String actor,PermissionDataScope scope,String c){var p=plan(a,planId);authority(a,cycle(a,p.getCycleId()),actor,scope);check(p.getVersion(),i.planRecordVersion());if(p.getStatus()!=SuccessionContinuityPlan.Status.FINALIZED)throw new IllegalStateException("Only a finalized continuity plan may create a referral packet");var b=bench.findByIdAndAgencyIdAndContinuityPlanId(i.benchEntryId(),a,planId).orElseThrow(()->new ResourceNotFoundException("Bench coverage entry not found"));currentMembership(a,b);if(referrals.existsByAgencyIdAndBenchEntryIdAndStatusIn(a,b.getId(),List.of(SuccessionRspReferralPacket.Status.DRAFT,SuccessionRspReferralPacket.Status.AUTHORIZED,SuccessionRspReferralPacket.Status.SENT,SuccessionRspReferralPacket.Status.RECEIVED,SuccessionRspReferralPacket.Status.UNDER_REVIEW)))throw new OptimisticConflictException("An active referral already exists for this bench entry");var r=new SuccessionRspReferralPacket(a,p,b,i.referralReason(),i.employeeVisibleNotice(),i.restrictedRationale(),actor);candidateAction(a,r,actor);if(i.vacancyPublicationId()!=null&&!i.vacancyPublicationId().isBlank())r.linkVacancy(vacancy(a,p,i.vacancyPublicationId()));r=referrals.saveAndFlush(r);event(a,r,"CREATED",i.employeeVisibleNotice(),i.restrictedRationale(),actor);var out=referralResponse(a,r);record(a,"CREATE_SUCCESSION_RSP_REFERRAL",r,out,i.restrictedRationale(),c);return out;}
    @Override public ReferralResponse updateReferral(String a,String id,ReferralUpdate i,String actor,PermissionDataScope scope,String c){var r=referralAction(a,id,actor,scope);check(r.getVersion(),i.recordVersion());r.updateNarrative(i.referralReason(),i.employeeVisibleNotice(),i.restrictedRationale());referrals.saveAndFlush(r);event(a,r,"UPDATED",i.employeeVisibleNotice(),i.restrictedRationale(),actor);return audited(a,"UPDATE_SUCCESSION_RSP_REFERRAL",r,i.restrictedRationale(),c);}
    @Override public ReferralResponse linkVacancy(String a,String id,VacancyLink i,String actor,PermissionDataScope scope,String c){var r=referralAction(a,id,actor,scope);check(r.getVersion(),i.recordVersion());r.linkVacancy(vacancy(a,plan(a,r.getContinuityPlanId()),i.vacancyPublicationId()));referrals.saveAndFlush(r);event(a,r,"VACANCY_LINKED","Referral linked to an authorized RSP vacancy","Vacancy publication "+i.vacancyPublicationId(),actor);return audited(a,"LINK_SUCCESSION_RSP_VACANCY",r,i.vacancyPublicationId(),c);}
    @Override public ReferralResponse authorizeReferral(String a,String id,ReferralTransition i,String actor,PermissionDataScope scope,String c){agencyWide(scope,"Referral authorization");var r=referral(a,id);candidateAction(a,r,actor);check(r.getVersion(),i.recordVersion());currentMembership(a,benchFor(a,r));requireVacancyCurrent(a,r);r.authorize(actor,i.restrictedReason(),Instant.now());referrals.saveAndFlush(r);event(a,r,"AUTHORIZED",i.employeeVisibleReason(),i.restrictedReason(),actor);return audited(a,"AUTHORIZE_SUCCESSION_RSP_REFERRAL",r,i.restrictedReason(),c);}
    @Override public ReferralResponse sendReferral(String a,String id,ReferralTransition i,String actor,PermissionDataScope scope,String c){var r=referralAction(a,id,actor,scope);check(r.getVersion(),i.recordVersion());currentMembership(a,benchFor(a,r));requireVacancyCurrent(a,r);r.send(actor,i.restrictedReason(),Instant.now());referrals.saveAndFlush(r);event(a,r,"SENT",i.employeeVisibleReason(),i.restrictedReason(),actor);return audited(a,"SEND_SUCCESSION_RSP_REFERRAL",r,i.restrictedReason(),c);}
    @Override public ReferralResponse receiveReferral(String a,String id,ReferralTransition i,String actor,PermissionDataScope scope,String c){agencyWide(scope,"RSP referral receipt");var r=referral(a,id);candidateAction(a,r,actor);check(r.getVersion(),i.recordVersion());requireVacancyCurrent(a,r);r.receive(actor,i.restrictedReason(),Instant.now());referrals.saveAndFlush(r);event(a,r,"RECEIVED",i.employeeVisibleReason(),i.restrictedReason(),actor);return audited(a,"RECEIVE_SUCCESSION_RSP_REFERRAL",r,i.restrictedReason(),c);}
    @Override public ReferralResponse updateReferralStatus(String a,String id,ReferralStatus i,String actor,PermissionDataScope scope,String c){agencyWide(scope,"RSP referral status");var r=referral(a,id);candidateAction(a,r,actor);check(r.getVersion(),i.recordVersion());r.updateRspStatus(i.status(),i.restrictedReason());referrals.saveAndFlush(r);event(a,r,"STATUS_UPDATED",i.employeeVisibleReason(),i.restrictedReason(),actor);return audited(a,"UPDATE_SUCCESSION_RSP_REFERRAL_STATUS",r,i.restrictedReason(),c);}
    @Override public ReferralResponse withdrawReferral(String a,String id,ReferralTransition i,String actor,PermissionDataScope scope,String c){var r=referralAction(a,id,actor,scope);check(r.getVersion(),i.recordVersion());r.withdraw(i.restrictedReason());referrals.saveAndFlush(r);event(a,r,"WITHDRAWN",i.employeeVisibleReason(),i.restrictedReason(),actor);return audited(a,"WITHDRAW_SUCCESSION_RSP_REFERRAL",r,i.restrictedReason(),c);}

    private RspReferralSourcePort.VacancySnapshot vacancy(String a,SuccessionContinuityPlan p,String id){var v=rsp.findVacancy(a,id).orElseThrow(()->new ResourceNotFoundException("RSP vacancy publication not found"));if(!Set.of("APPROVED","PUBLISHED").contains(v.status()))throw new IllegalStateException("Only an approved or published RSP vacancy may be linked");if(!p.getJobPositionId().equals(v.jobPositionId())||p.getPlantillaId()!=null&&!p.getPlantillaId().equals(v.plantillaId()))throw new IllegalArgumentException("RSP vacancy does not match the continuity-plan target position");return v;}
    private void requireVacancyCurrent(String a,SuccessionRspReferralPacket r){if(r.getVacancyPublicationId()==null)throw new IllegalStateException("An authorized matching RSP vacancy must be linked before handoff");var v=vacancy(a,plan(a,r.getContinuityPlanId()),r.getVacancyPublicationId());if(!Objects.equals(r.getVacancyRecordVersion(),v.recordVersion())||!Objects.equals(r.getVacancyFingerprint(),v.sourceFingerprint()))throw new OptimisticConflictException("Linked RSP vacancy changed; create a refreshed referral packet");}
    private void currentMembership(String a,SuccessionBenchCoverageEntry b){var current=memberships.findFirstByAgencyIdAndPoolDecisionIdOrderByEventSequenceDesc(a,b.getPoolDecisionId()).orElseThrow(()->new ResourceNotFoundException("Membership lineage not found"));LocalDate today=LocalDate.now(AGENCY_ZONE);if(!current.getId().equals(b.getMembershipEventId())||current.getResultingStatus()!=SuccessionPoolMembershipEvent.ResultingStatus.ACTIVE||current.getExpiresOn()==null||today.isAfter(current.getExpiresOn())||today.isBefore(current.getEffectiveOn()))throw new OptimisticConflictException("Bench membership snapshot is no longer active and current");}
    private SuccessionBenchCoverageEntry benchFor(String a,SuccessionRspReferralPacket r){return bench.findByIdAndAgencyIdAndContinuityPlanId(r.getBenchEntryId(),a,r.getContinuityPlanId()).orElseThrow(()->new ResourceNotFoundException("Bench coverage entry not found"));}
    private void event(String a,SuccessionRspReferralPacket r,String type,String visible,String restricted,String actor){var previous=referralEvents.findFirstByAgencyIdAndReferralIdOrderByEventSequenceDesc(a,r.getId()).orElse(null);referralEvents.saveAndFlush(new SuccessionRspReferralEvent(a,r.getId(),previous,type,r.getStatus().name(),visible,restricted,actor,Instant.now()));}
    private ReferralResponse audited(String a,String action,SuccessionRspReferralPacket r,String reason,String c){var out=referralResponse(a,r);record(a,action,r,out,reason,c);return out;}
    private PlanResponse planResponse(String a,SuccessionContinuityPlan p){var entries=bench.findByAgencyIdAndContinuityPlanIdOrderByEmployeeNo(a,p.getId()).stream().map(b->new BenchResponse(b.getId(),b.getCandidateId(),b.getPoolDecisionId(),b.getMembershipEventId(),b.getEmployeeNo(),b.getEmployeeName(),b.getReadinessLevelCode(),b.getMembershipEffectiveOn(),b.getMembershipExpiresOn(),b.getDevelopmentPlanId(),b.getDevelopmentStatus(),b.getSnapshotAt())).toList();return new PlanResponse(p.getId(),p.getVersion(),p.getRiskReviewId(),p.getCycleId(),p.getDesignationId(),p.getTargetType(),p.getTargetId(),p.getJobPositionId(),p.getPositionName(),p.getPlantillaId(),p.getPlantillaName(),p.getRiskLevel(),p.getRiskReasonSnapshot(),p.getCriticalFunctions(),p.getInterimArrangement(),p.getContinuityActions(),p.getActivationTriggers(),p.getTargetRecoveryDays(),p.getReviewOn(),p.getStatus().name(),p.getCoverageStatus().name(),p.getBenchCount(),p.getSubmittedBy(),p.getSubmittedAt(),p.getApprovedBy(),p.getApprovedAt(),p.getApprovalReason(),p.getFinalizedBy(),p.getFinalizedAt(),entries);}
    private ReferralResponse referralResponse(String a,SuccessionRspReferralPacket r){var es=referralEvents.findByAgencyIdAndReferralIdOrderByEventSequence(a,r.getId()).stream().map(e->new ReferralEventResponse(e.getId(),e.getPreviousEventId(),e.getEventSequence(),e.getEventType(),e.getResultingStatus(),e.getEmployeeVisibleReason(),e.getRestrictedReason(),e.getRecordedBy(),e.getRecordedAt())).toList();return new ReferralResponse(r.getId(),r.getVersion(),r.getReferralCode(),r.getContinuityPlanId(),r.getBenchEntryId(),r.getCandidateId(),r.getEmployeeNo(),r.getEmployeeName(),r.getReadinessLevelCode(),r.getTargetJobPositionId(),r.getTargetPositionName(),r.getTargetPlantillaId(),r.getTargetPlantillaName(),r.getMembershipExpiresOn(),r.getReferralReason(),r.getEmployeeVisibleNotice(),r.getRestrictedRationale(),r.getVacancyPublicationId(),r.getVacancyRequestId(),r.getVacancyStatus(),r.getVacancyRecordVersion(),r.getVacancyFingerprint(),r.getVacancyFetchedAt(),r.getStatus().name(),r.getCreatedByActor(),r.getAuthorizedBy(),r.getAuthorizedAt(),r.getSentBy(),r.getSentAt(),r.getReceivedBy(),r.getReceivedAt(),r.getStatusReason(),es);}
    private SuccessionContinuityPlan plan(String a,String id){return plans.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Continuity plan not found"));}private SuccessionCycle cycle(String a,String id){return cycles.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Succession cycle not found"));}private SuccessionCriticalPositionDesignation designation(String a,String id){return designations.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Critical-position designation not found"));}private SuccessionRspReferralPacket referral(String a,String id){return referrals.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("RSP referral packet not found"));}
    private SuccessionRspReferralPacket referralAction(String a,String id,String actor,PermissionDataScope scope){var r=referral(a,id);authority(a,cycle(a,plan(a,r.getContinuityPlanId()).getCycleId()),actor,scope);candidateAction(a,r,actor);return r;}
    private void candidateAction(String a,SuccessionRspReferralPacket r,String actor){if(r.getEmployeeNo().equalsIgnoreCase(actor))throw new AccessDeniedException("Candidate cannot decide their own RSP referral");String charter=plan(a,r.getContinuityPlanId()).getCharterVersionId();boolean conflict=conflicts.existsByAgencyIdAndCharterVersionIdAndDeclaringEmployeeNoIgnoreCaseAndRelatedEmployeeNoIgnoreCaseAndStatus(a,charter,actor,r.getEmployeeNo(),SuccessionCommitteeConflict.Status.ACTIVE)||conflicts.existsByAgencyIdAndCharterVersionIdAndDeclaringEmployeeNoIgnoreCaseAndRelatedEmployeeNoIgnoreCaseAndStatus(a,charter,r.getEmployeeNo(),actor,SuccessionCommitteeConflict.Status.ACTIVE);if(conflict)throw new AccessDeniedException("An active conflict blocks action on this candidate referral");}
    private boolean visible(String a,SuccessionContinuityPlan p,String actor,PermissionDataScope scope){return scope==PermissionDataScope.AGENCY_WIDE||scope==PermissionDataScope.ASSIGNED_RECORDS&&activeMember(a,p.getCharterVersionId(),actor);}
    private void authorize(String a,SuccessionContinuityPlan p,String actor,PermissionDataScope scope){if(!visible(a,p,actor,scope))throw new AccessDeniedException("Continuity record is outside the permitted confidential scope");}
    private void authority(String a,SuccessionCycle cycle,String actor,PermissionDataScope scope){if(scope==PermissionDataScope.AGENCY_WIDE)return;if(scope!=PermissionDataScope.ASSIGNED_RECORDS||!activeMember(a,cycle.getCharterVersionId(),actor))throw new AccessDeniedException("Only an assigned succession committee member may act on this continuity record");}
    private boolean activeMember(String a,String charter,String actor){LocalDate today=LocalDate.now(AGENCY_ZONE);return members.findByAgencyIdAndCharterVersionIdOrderByMemberRole(a,charter).stream().anyMatch(m->m.getEmployeeNo().equalsIgnoreCase(actor)&&!today.isBefore(m.getEffectiveFrom())&&(m.getEffectiveTo()==null||!today.isAfter(m.getEffectiveTo())));}
    private static void agencyWide(PermissionDataScope scope,String action){if(scope!=PermissionDataScope.AGENCY_WIDE)throw new AccessDeniedException(action+" requires Agency Wide authority");}
    private static void check(long actual,Long expected){if(expected==null||actual!=expected)throw new OptimisticConflictException("Record changed; reload and retry");}
    private void record(String a,String action,com.primehr.rsp.domain.RspAuditedEntity entity,Object after,String reason,String c){audit.record(a,action,entity.getClass().getSimpleName(),entity.getId(),null,entity.getVersion(),null,after,reason,c);}
}
